                              int C_out, int H_out, int W_out)
{
    extern __shared__ float smem[];
    float* s_in_base = smem;
    float* s_w_base = s_in_base + 3 * PATCH * PATCH;
    float* s_bias_base = s_w_base + OC_BLOCK * 3 * KSIZE * KSIZE;
    #define S_IN(c, r, col) s_in_base[((c) * PATCH + (r)) * PATCH + (col)]
    #define S_W(ocb, c, ky, kx) s_w_base[((((ocb) * 3 + (c)) * KSIZE + (ky)) * KSIZE + (kx))]
    #define S_BIAS(ocb) s_bias_base[(ocb)]
    const int n  = blockIdx.z;
    const int oc0 = blockIdx.y * OC_BLOCK;
    const int tiles_w = (W_out + TILE - 1) / TILE;
    const int ty0 = (blockIdx.x / tiles_w) * TILE;
    const int tx0 = (blockIdx.x % tiles_w) * TILE;
    const int tid = threadIdx.y * blockDim.x + threadIdx.x;
    const int nthreads = blockDim.x * blockDim.y;
    const int in_y0 = ty0 * STRIDE - PAD;
    const int in_x0 = tx0 * STRIDE - PAD;
    // Cooperatively load the input patch once per block and reuse it across OC_BLOCK.
    for (int idx = tid; idx < 3 * PATCH * PATCH; idx += nthreads) {
        const int c   = idx / (PATCH * PATCH);
        const int rem = idx % (PATCH * PATCH);
        const int r   = rem / PATCH;
        const int col = rem % PATCH;
        const int iy = in_y0 + r;
        const int ix = in_x0 + col;
        float v = 0.0f;
        if (iy >= 0 && iy < H && ix >= 0 && ix < W)
            v = input[((n * C_in + c) * H + iy) * W + ix];
        S_IN(c, r, col) = v;
    }
    // Cooperatively load this block's group of filters.
    for (int idx = tid; idx < OC_BLOCK * 3 * KSIZE * KSIZE; idx += nthreads) {
        const int ocb  = idx / (3 * KSIZE * KSIZE);
        const int rem  = idx % (3 * KSIZE * KSIZE);
        const int c    = rem / (KSIZE * KSIZE);
        const int rem2 = rem % (KSIZE * KSIZE);
        const int ky   = rem2 / KSIZE;
        const int kx   = rem2 % KSIZE;
        const int oc   = oc0 + ocb;
        float v = 0.0f;
        if (oc < C_out)
            v = weight[((oc * 3 + c) * KSIZE + ky) * KSIZE + kx];
        S_W(ocb, c, ky, kx) = v;
