    const int oh = ty0 + threadIdx.y;
    const int ow = tx0 + threadIdx.x;
    if (oh < H_out && ow < W_out) {
        float acc[OC_BLOCK];
        #pragma unroll
        for (int ocb = 0; ocb < OC_BLOCK; ++ocb) {
            acc[ocb] = S_BIAS(ocb);
