                }
            }
        }
        #pragma unroll
        for (int ocb = 0; ocb < OC_BLOCK; ++ocb) {
            const int oc = oc0 + ocb;
            if (oc < C_out) {
                output[((n * C_out + oc) * H_out + oh) * W_out + ow] = acc[ocb];
